export function teamRatings(team){const players=(team?.xi||[]).map(n=>team.players?.[n]).filter(Boolean);if(!players.length)players.push(...(team?.players||[]));if(!players.length&&team?.ratingBaseline)return {...team.ratingBaseline};if(!players.length)return {bat:0,bowl:0,field:0,available:false};const bestAverage=(key,count)=>Math.round(players.map(p=>p[key]).sort((a,b)=>b-a).slice(0,Math.min(count,players.length)).reduce((n,value)=>n+value,0)/Math.min(count,players.length));return {bat:bestAverage('bat',7),bowl:bestAverage('bowl',5),field:bestAverage('field',players.length),available:true};}
