function alignLegacyRatings(s){if(s.ratingsModel>=2||s.active)return;const align=p=>{if(p.role==='Batter'){p.bat=Math.max(58,p.bat);p.bowl=Math.min(55,p.bowl);}else if(p.role==='Keeper'){p.bat=Math.max(54,p.bat);p.bowl=Math.min(32,p.bowl);p.field=Math.max(65,p.field);}else if(p.role==='All-rounder'){p.bat=Math.max(50,p.bat);p.bowl=Math.max(50,p.bowl);}else if(p.role==='Bowler'){p.bat=Math.min(55,p.bat);p.bowl=Math.max(60,p.bowl);}for(const k of ['bat','bowl','field'])p.potential[k]=Math.max(p.potential[k],p[k]);};for(const t of s.teams)for(const p of t.players)align(p);for(const p of s.freeAgents||[])align(p);s.ratingsModel=2;}
