export function setBattingPosition(s,id,position){return setPlayerPosition(s,id,position);}
export function upgradeAcademy(s){if(s.active)throw Error('Finish the current match before upgrading the academy.');if(s.phase!=='Pre-season')throw Error('Academy upgrades are available before a new season.');const academy=setupDevelopment(s);if(academy.level>=5)throw Error('Your academy is already at its highest level.');const cost=academy.level;if(academy.tokens<cost)throw Error(`You need ${cost} academy token${cost===1?'':'s'}; you have ${academy.tokens}.`);academy.tokens-=cost;academy.level++;}
function developSeason(s){const academy=setupDevelopment(s),retirements=[];for(const team of s.teams){let aiTrainee=null;if(team.id!==s.team){aiTrainee=team.players.filter(p=>p.age<30).sort((a,b)=>Math.max(b.potential.bat-b.bat,b.potential.bowl-b.bowl,b.potential.field-b.field)-Math.max(a.potential.bat-a.bat,a.potential.bowl-a.bowl,a.potential.field-a.field))[0];}for(const p of [...team.players]){const focus=team.id===s.team?academy.training[p.id]:p===aiTrainee?['bat','bowl','field'].sort((a,b)=>(p.potential[b]-p[b])-(p.potential[a]-p[a]))[0]:null;if(focus&&p[focus]<p.potential[focus]){const staffBonus=team.id===s.team?coachTrainingBonus(team,focus)+(team.club?.staff?.['Fitness coach']?.rating>=85?1:0):0,facilityBonus=team.id===s.team?Math.floor(((team.club?.facilities?.training||1)-1)/2):0;p[focus]=Math.min(p.potential[focus],p[focus]+(team.id===s.team?2+Math.floor(academy.level/2)+staffBonus+facilityBonus:1));}if(team.id===s.team&&team.captain===p.id){p.leadership=Math.min(100,p.leadership+(team.club?.staff?.['Assistant coach']?.rating>=80?2:1));p.tacticalAwareness=Math.min(100,p.tacticalAwareness+(team.club?.staff?.['Assistant coach']?.rating>=90?2:1));}p.age++;if(p.age>34)for(const key of ['bat','bowl','field'])if(p[key]>30)p[key]--;if(p.age>=38){const index=team.players.indexOf(p),replacement=generateAgent(s,p.role);replacement.age=18+s.nextPlayerId%4;replacement.potential=Object.fromEntries(['bat','bowl','field'].map(key=>[key,Math.min(100,replacement[key]+12+s.nextPlayerId%8)]));replacement.contract=makeContract(replacement,s.season+1,s.competition==='world'?2:3);replacement.wage=Math.round(6000+(replacement.bat+replacement.bowl+replacement.field)*38);team.players[index]=replacement;if(team.captain===p.id)team.captain=replacement.id;if(team.viceCaptain===p.id)team.viceCaptain=replacement.id;for(const squad of Object.values(team.formatSquads||{})){if(squad.captain===p.id)squad.captain=replacement.id;if(squad.viceCaptain===p.id)squad.viceCaptain=replacement.id;}retirements.push({name:p.name,role:p.role,age:p.age,team:team.name,replacement:replacement.name});}}}academy.tokens++;academy.training={};setupDevelopment(s);return retirements;}
export function makeFixtures(season=1,teamCount=6){if(!Number.isInteger(teamCount)||teamCount<4||teamCount%2)throw Error("An even number of clubs is required");const fixtures=[];let a=Array.from({length:teamCount},(_,n)=>n);for(let r=1;r<teamCount;r++){for(let j=0;j<teamCount/2;j++){const pair=[a[j],a[teamCount-1-j]];if(season%2===0)pair.reverse();fixtures.push({id:fixtures.length,round:r,home:pair[0],away:pair[1],stage:'League'});}a=[a[0],a[teamCount-1],...a.slice(1,teamCount-1)];}return fixtures;}
export function competitionKeys(s){const keys=s.competition==='combined'?(s.competitions||['sydney','empire','franchise']):[s.competition||'empire'];return s.competition==='combined'&&s.formatMode!=='ALL'&&s.format!=='T20'?keys.filter(key=>key!=='franchise'):keys;}
export function careerCompetition(s){return s.competition==='combined'?(s.teams[s.team]?.competition||'sydney'):s.competition||'empire';}
