function reviewObjectives(s,summary){const objectives=careerObjectives(s),met=objectives.filter(item=>item.complete).length;summary.objectives=objectives.map(({id,label,progress,target,complete})=>({id,label,progress,target,complete}));summary.boardReview={met,total:objectives.length,approved:met>=2};if(s.competition!=='world'){const club=initializeClub(s.teams[s.team],s.seed);club.reputation=Math.max(1,Math.min(100,club.reputation+(met>=2?2:-2)));club.boardConfidence=Math.max(1,Math.min(100,(club.boardConfidence??55)+(met>=2?8:-12)));summary.boardReview.confidence=club.boardConfidence;}}
