function snapshot(p,score=null){const form=score?.form||{matches:[]},results=form.matches||[],confidence=results.length?Math.max(20,Math.min(80,Math.round(50+results.reduce((sum,m)=>sum+(m.result==='W'?10:m.result==='D'?3:-7),0)/results.length))):50;return {id:p.id,name:p.name,role:p.role,bat:Math.max(8,Math.min(100,p.bat+Math.round((score?.form?.batBoost||0)*.4)+Math.round((confidence-50)/25))),bowl:Math.max(8,Math.min(100,p.bowl+Math.round((score?.form?.bowlBoost||0)*.4)+Math.round((confidence-50)/25))),field:p.field,confidence,age:p.age??null,potential:p.potential?{...p.potential}:null,fatigue:p.fatigue||0,...(p.injury?{injury:{...p.injury}}:{})};}
