export function innings(bat,bowl,limit=120,target=null){return {bat,bowl,limit,target,runs:0,wickets:0,balls:0,striker:0,non:1,next:2,free:false,extras:{wd:0,nb:0,b:0,lb:0},batting:Array.from({length:11},()=>({runs:0,balls:0,fours:0,sixes:0,out:null})),bowling:Array.from({length:11},()=>({runs:0,balls:0,wickets:0})),log:[],done:false};}
